-- Correct the compact legacy-sheet play counts against the source CSV.
-- Reporting days are 09:00 JST (= 00:00 UTC) through 08:59 JST next day.
-- The first-pass seed dictionary/row keys are retained; only play_count is
-- reconciled to the verified transition-based source aggregate.
-- Verified: 33 days, 1,822 day/track rows, 14,119 inferred plays.

WITH RECURSIVE
days AS (
  SELECT
    CAST(json_extract(value,'$[0]') AS INTEGER) AS day_id,
    json_extract(value,'$[1]') AS play_date
  FROM json_each('[[1,"2025-06-06"],[2,"2025-06-08"],[3,"2025-06-09"],[4,"2025-06-10"],[5,"2025-06-11"],[6,"2025-06-13"],[7,"2025-06-15"],[8,"2025-06-16"],[9,"2025-06-17"],[10,"2025-06-18"],[11,"2025-06-19"],[12,"2025-06-20"],[13,"2025-06-22"],[14,"2025-06-24"],[15,"2025-06-27"],[16,"2025-06-29"],[17,"2025-06-30"],[18,"2025-07-02"],[19,"2025-07-03"],[20,"2025-07-10"],[21,"2025-07-11"],[22,"2025-07-12"],[23,"2025-07-14"],[24,"2025-07-15"],[25,"2025-07-18"],[26,"2025-07-20"],[27,"2025-07-21"],[28,"2025-07-24"],[29,"2025-07-25"],[30,"2025-07-26"],[31,"2025-07-27"],[32,"2025-07-28"],[33,"2025-07-29"]]')
),
packed(data) AS (
  VALUES('')
),
positions(pos) AS (
  SELECT 1
  UNION ALL
  SELECT pos+6 FROM positions,packed WHERE pos+6<=length(data)
),
plays AS (
  SELECT
    (instr('0123456789ABCDEF',substr(data,pos,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+1,1))-1) AS day_id,
    (instr('0123456789ABCDEF',substr(data,pos+2,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+3,1))-1) AS track_id,
    (instr('0123456789ABCDEF',substr(data,pos+4,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+5,1))-1) AS play_count
  FROM positions,packed
),
corrected AS (
  SELECT
    'legacy-sheet|' || days.play_date || '|' || plays.track_id AS row_key,
    plays.play_count
  FROM plays
  JOIN days USING(day_id)
)
UPDATE sh_pages_track_history_read_model AS target
SET
  row_json=json_set(
    target.row_json,
    '$.play_count',
    (SELECT corrected.play_count FROM corrected WHERE corrected.row_key=target.row_key)
  ),
  updated_at=1790208000000
WHERE target.row_key IN (SELECT row_key FROM corrected);
